-- Ojigi lengkap: 24 soal (8 teks + 6 bergambar + 10 teks lanjutan). Aman diulang.
alter table soal add column if not exists pertanyaan_id text;
alter table soal add column if not exists penjelasan_id text;
alter table soal add column if not exists kata jsonb;
alter table soal add column if not exists pilihan_gambar jsonb;
begin;
delete from soal where kategori='宿泊分野' and urutan between 601 and 608;
delete from soal where kategori='宿泊分野' and urutan between 610 and 625;
commit;
